  const elsewhere = join(d, 'elsewhere');
  mkdirSync(elsewhere, { recursive: true });
  for (const f of readdirSync(area)) renameSync(join(area, f), join(elsewhere, f));
  rmSync(area, { recursive: true, force: true });
  symlinkSync(relative(dirname(area), elsewhere), area);
  // The fixture's own pre-rendered index moved into the target directory, so the claim
  // to test is not "absent afterwards" but "nothing new arrived because of this write".
  const before = readdirSync(elsewhere).sort().join(',');
  const res = run(SYNC, ['--write', '--root', d]);
  return [
    { ok: res.code === 2, why: `write exit ${res.code} (expected 2 REFUSED)` },
    { ok: /SYMLINK_ANCESTOR/.test(res.out), why: 'refusal names the symlinked ancestor: ' + (res.out.match(/REFUSED[^\n]*/) || [''])[0] },
    { ok: readdirSync(elsewhere).sort().join(',') === before, why: 'the directory the link points at gained no file: ' + before + ' -> ' + readdirSync(elsewhere).sort().join(',') },
  ];
});

control('NEG-58 a symlinked target is refused and its referent keeps its bytes', (d) => {
  const idx = join(d, CATALOG_INDEX_PATH);
  const referent = join(d, 'referent.md');
  writeFileSync(referent, 'ORIGINAL BYTES\n');
  rmSync(idx);
  symlinkSync(relative(dirname(idx), referent), idx);
  const res = run(SYNC, ['--write', '--root', d]);
  return [
    { ok: res.code === 2, why: `write exit ${res.code} (expected 2 REFUSED)` },
    { ok: /SYMLINK_TARGET/.test(res.out), why: 'refusal names the symlinked target: ' + (res.out.match(/REFUSED[^\n]*/) || [''])[0] },
    { ok: readFileSync(referent, 'utf8') === 'ORIGINAL BYTES\n', why: 'the file behind the link is byte-identical to what it was before' },
  ];
});

control('NEG-59 being inside a named area does not authorize a normative file', (d) => {
  // The area now contains the generated index, so the area check on its own would let
  // ids.yaml and README.md through. The exact-file rule is what stops it.
  const readme = checkGeneratedTarget(d, 'docs/contracts/engineering-baseline/README.md');
  const ids = checkGeneratedTarget(d, 'docs/contracts/engineering-baseline/ids.yaml');
  const index = checkGeneratedTarget(d, CATALOG_INDEX_PATH);
  return [
    { ok: !readme.ok && /NOT_GENERATED_FILE/.test(readme.why), why: 'README.md: ' + readme.why },
    { ok: !ids.ok && /NOT_GENERATED_FILE/.test(ids.why), why: 'ids.yaml: ' + ids.why },
    { ok: index.ok, why: 'only INDEX.md is listed, and it is listed by full path' },
    { ok: !isWriteAllowed('docs/contracts/engineering-baseline/ids.yaml'), why: 'docs:sync also refuses the catalog source' },
  ];
});

control('NEG-60 a hard-linked target is refused, the second name keeps its bytes', (d) => {
  // Same inode under two names passes every path check: regular file, no symlink, real
  // parent. It still means the bytes land in a file something else reads.
  const idx = join(d, CATALOG_INDEX_PATH);
  const other = join(d, 'other-name.md');
  linkSync(idx, other);
  const before = readFileSync(other, 'utf8');
  const res = run(SYNC, ['--write', '--root', d]);
  // Add drift through the linked name so the run has a reason to rewrite; the boundary
  // check runs before any content comparison, so the refusal must come first either way.
  const drifted = read(d, CATALOG_INDEX_PATH) + 'drift\n';
  writeFile(d, CATALOG_INDEX_PATH, drifted);
  const res2 = run(SYNC, ['--write', '--root', d]);
  return [
    // Two names of one inode share bytes by definition, so the claim is not "the other
    // name is unchanged" but "the only bytes present are the ones the control wrote".
    { ok: res.code === 2 && /HARDLINK_TARGET/.test(res.out), why: `exit ${res.code} with the boundary refusal even when bytes already match: ` + (res.out.match(/REFUSED[^\n]*/) || [''])[0] },
    { ok: res2.code === 2, why: `write exit ${res2.code} (expected 2 REFUSED) when the bytes differ` },
    { ok: /HARDLINK_TARGET/.test(res2.out) && /nlink=2/.test(res2.out), why: 'refusal names the hard link and its nlink: ' + (res2.out.match(/REFUSED[^\n]*/) || [''])[0] },
    { ok: readFileSync(other, 'utf8') === drifted, why: 'the inode holds exactly the drift the control wrote; the generator added nothing' },
    { ok: readFileSync(idx, 'utf8') === readFileSync(other, 'utf8'), why: `both names still address one inode (was ${before.length} bytes before linking)` },
  ];
});

control('POS-13 the catalog index lists the catalog and is accepted as fresh', (d) => {
  const idx = read(d, CATALOG_INDEX_PATH);
  const ids = (read(d, 'docs/contracts/engineering-baseline/ids.yaml').match(/id:\s*([A-Z]+-EB-\S+)/g) || []).map((s) => s.split(/[:\s]+/)[1]);
  const missing = ids.filter((id) => id && !idx.includes(id));
  return [
    { ok: ids.length > 0 && missing.length === 0, why: missing.length ? 'index lacks ' + missing.join(', ') : 'index names all ' + ids.length + ' catalog ids in the fixture' },
    expectRun('sync --check', run(SYNC, ['--check', '--root', d]), 0, 'blocking=0'),
  ];
});

control('NEG-55 a hand-edited catalog index is refused as stale', (d) => {
  // Someone "fixing a typo" in the generated file is the realistic form of this drift,
  // so the control edits the file rather than deleting it.
  // Any byte of divergence is staleness, so the edit appends rather than betting on a
  // particular rendered line: an earlier version of this control replaced a string the
  // fixture does not render, quietly became a no-op, and reported a passing-looking
  // exit 0. Appending cannot degrade that way.
  writeFile(d, CATALOG_INDEX_PATH, read(d, CATALOG_INDEX_PATH) + 'hand-edited line\n');
  return [expectBlocking('sync --check', run(SYNC, ['--check', '--root', d]), 'STALE_GENERATED_CATALOG')];
});

control('NEG-56 an ungenerated catalog index is visible and agrees across entry points', (d) => {
  rmSync(join(d, CATALOG_INDEX_PATH));
  const res = run(SYNC, ['--check', '--root', d]);
  const failCodes = (res.out.match(/^FAIL ([A-Z_]+)/gm) || []).map((l) => l.slice(5));
  const warnCodes = (res.out.match(/^WARN ([A-Z_]+)/gm) || []).map((l) => l.slice(5));
  return [
    { ok: warnCodes.includes('CATALOG_NOT_GENERATED'), why: 'warn set: [' + (warnCodes.join(',') || 'empty') + ']' },
    { ok: !failCodes.includes('CATALOG_NOT_GENERATED'), why: 'a recorded gap is not a refusal until the path is on the write allow-list' },
    // All three entry points must reach the same verdict on the same input. This
    // assertion exists because the generator's own --check was found exiting 1 on the
    // very finding the probe called non_blocking — and that discrepancy was then
    // reported as a pass. Asserted now rather than trusted.
    expectRun('gen-current-state --check', run(GEN, ['--check', '--root', d]), 0, 'blocking=0'),
  ];
});

control('NEG-54 an id-catalog edit makes the view stale, not silently fresh', (d) => {
  // The view resolves every refs entry through ids.yaml but used to record only the
  // registry hash, so a catalog edit kept the view "fresh" while the meaning of its
  // refs had moved. This is the case that field exists for.
  writeFile(d, 'docs/contracts/engineering-baseline/ids.yaml', read(d, 'docs/contracts/engineering-baseline/ids.yaml') + '- id: INV-EB-0099\n  kind: invariant\n  statement: added after the view was rendered\n  normative_status: proposed-not-ratified\n  owners: [EB-CTL]\n  source_anchor: docs/glossary.md\n');
  return [expectBlocking('sync --check', run(SYNC, ['--check', '--root', d]), 'STALE_GENERATED_VIEW')];
});

control('NEG-46 a second top-level entries: is refused and names the key', (d) => {
  // Same silent-loss class as a duplicated scalar, and it used to slip through because
  // the branch for this key continued before the duplicate check could see it.
  const reg = read(d, 'dev/engineering/registry.yaml');
  writeFile(d, 'dev/engineering/registry.yaml', reg + '\nentries:\n  - id: EB1-CTL-2\n    kind: gate\n    title: second block\n    decision_status: accepted\n    implementation_status: not_started\n    verification_status: not_verified\n    release_status: not_released\n    owners: [EB-CTL]\n    refs: [EB-ADR-0001]\n');
  return [expectBlocking('sync --check', run(SYNC, ['--check', '--root', d]), 'REGISTRY_PARSE', { detailIncludes: ':entries' })];
});

control('NEG-47 an entry field outside the closed set is refused', (d) => {
  // registry.schema.json has always claimed additionalProperties:false; this is the
  // rule that makes that claim true rather than aspirational.
  writeFile(d, 'dev/engineering/registry.yaml', read(d, 'dev/engineering/registry.yaml').replace('    owners: [EB-CTL]', '    ownerz: [EB-CTL]'));
  return [expectBlocking('sync --check', run(SYNC, ['--check', '--root', d]), 'REGISTRY_UNKNOWN_FIELD')];
});

control('NEG-45 duplicate top-level registry key is refused, not overwritten', (d) => {
  writeFile(d, 'dev/engineering/registry.yaml', `schema_version: 1\nschema_version: 2\nentries:\n` + read(d, 'dev/engineering/registry.yaml').split('\n').slice(1).join('\n'));
  return [expectRun('sync --check', run(SYNC, ['--check', '--root', d]), 1, 'registry-duplicate-key')];
});

// ------------------------------ run ------------------------------
// RUN_ROOT already exists: mkdtempSync created it at import time and owns it.

const boundary = [
  { path: 'dev/engineering/current-state.json', ok: true },
  { path: 'dev/engineering/registry.yaml', ok: false },
  { path: 'docs/STATUS.md', ok: false },
  { path: 'AGENTS.md', ok: false },
].map(({ path, ok }) => (GENERATED_FILES.includes(path) === ok)
  ? { ok: true, why: `${path} ${ok ? 'inside the generated area' : 'outside the generated area'}` }
  : { ok: false, why: `${path} boundary mismatch` });
const boundaryBad = boundary.filter((b) => !b.ok);
results.unshift({ name: 'POS-0b write boundary allow-list', ok: boundaryBad.length === 0, why: boundaryBad.length ? boundaryBad.map((b) => b.why).join(' | ') : 'generated-write.mjs names exactly the generated view' });

console.log(`doc-consistency controls   run_root=${relative(ROOT, RUN_ROOT)} (owned by pid ${process.pid})${KEEP ? '   --keep: left in place, nothing deleted' : ''}`);

const allowList = [
  { path: 'docs/contracts/engineering-baseline/ids.yaml', writable: false },
  { path: '.agents/notes/proposed/x.md', writable: false },
  { path: 'dev/agent-workflow/graph.yaml', writable: false },
  { path: 'docs/glossary.md', writable: false },
  { path: 'docs/plans/active/whatever.md', writable: false },
  { path: 'some/random/file.md', writable: false },
  { path: 'dev/engineering/current-state.json', writable: true },
].map(({ path, writable }) => isWriteAllowed(path) === writable
  ? { ok: true, why: `${path} ${writable ? 'writable' : 'refused'}` }
  : { ok: false, why: `${path} authority mismatch` });
const bad = allowList.filter((a) => !a.ok);
results.unshift({ name: 'POS-0 write authority allow-list', ok: bad.length === 0, why: bad.length ? bad.map((b) => b.why).join(' | ') : 'only the generated view is writable' });

let failed = 0;
for (const r of results) {
  if (!r.ok) failed += 1;
  console.log(`${r.ok ? 'PASS' : 'FAIL'}  ${r.name}\n      ${r.why}`);
}
// Sweep only our own run root. An older root, a --keep root, or anything a parallel
// run created is never touched: there is no fixed shared path any more.
if (!KEEP && OWNED.has(RUN_ROOT)) rmSync(RUN_ROOT, { recursive: true, force: true });
console.log(`controls=${results.length} failed=${failed}  scope: static document checks only (no C1/C2/C3, no runtime behaviour)`);
process.exit(failed ? 1 : 0);

#!/usr/bin/env node
// EB1-E docs:probe — fast document consistency probe (Engineering Baseline, first version).
//
//   pnpm docs:probe -- --base origin/master          PR / branch mode
//   pnpm docs:probe -- --worktree-only               local uncommitted work
//   node scripts/docs-probe.mjs --root <dir> --json  scratch fixture (controls)
//
// Scope is real Git state: merge-base..HEAD plus staged, unstaged and untracked
// paths. A --base that cannot be resolved is REFUSED (exit 2): an unknown base
// must never degrade into "nothing changed, all green".
//
// This is a T0 check. It proves document/graph facts and artifact existence. It
// does not prove behaviour: no C1/C2/C3, no security negative, no permission
// reasoning. The output says so in `limits` so a green line cannot be quoted as
// "verified".
//
// Exit codes: 0 pass | 1 blocking findings | 2 REFUSED

import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve, dirname, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  makeCommitExists,
  allDocsForFullCheck,
  checkLinks,
  checkDeprecatedTerms,
  checkClaimsHaveEvidence,
  checkIdUniqueness,
  checkContractAnchors,
  checkPlanCitationBlocks,
  selectOwningDocs,
  BLOCKING_PREFIXES,
  contractShapeFindings,
  checkRatification,
} from './doc-checks.mjs';
import { run as runNotes } from './verify-agent-notes.mjs';
import { build as buildStateView, renderView } from './gen-current-state.mjs';

const BLOCKING = BLOCKING_PREFIXES; // single source of truth, shared with docs:sync --write
const LIMITS = [
  'T0 only: proves document facts, id/reference integrity and artifact existence; proves no runtime behaviour',
  'no C1/C2/C3 substitution and no security negative control here',
  'complements scripts/ci-pr-gate.mjs (graph-parse / state-freshness legs own current_contract pointer grammar and stay the merge gate); this probe does not re-implement them and cannot replace a leg',
  'semantic equivalence of prose remains a Contract Owner judgement',
  'natural-language claims are matched by conservative patterns; a novel phrasing can evade the pattern (reported as a limit, not as a pass)',
];

function git(root, args, allowFail = true) {
  try {
    return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' });
  } catch (e) {
    if (allowFail) return null;
    throw e;
  }
}

/** Committed + staged + unstaged + untracked paths, as repo-relative posix paths. */
export function changeScope(root, base) {
  const sets = { committed: [], staged: [], unstaged: [], untracked: [] };
  const lines = (s) => (s || '').split('\n').map((l) => l.trim()).filter(Boolean);
  if (base) {
    const mb = git(root, ['merge-base', base, 'HEAD']);
    if (!mb) return { refused: `BASE_UNRESOLVABLE:${base}` };
    sets.committed = lines(git(root, ['diff', '--name-only', `${mb.trim()}..HEAD`])).map(toPosix);
    sets.merge_base = mb.trim();
  }
  sets.staged = lines(git(root, ['diff', '--name-only', '--cached'])).map(toPosix);
  sets.unstaged = lines(git(root, ['diff', '--name-only'])).map(toPosix);
  sets.untracked = lines(git(root, ['ls-files', '--others', '--exclude-standard'])).map(toPosix);
  sets.all = [...new Set([...sets.committed, ...sets.staged, ...sets.unstaged, ...sets.untracked])].sort();
  return sets;
}

const toPosix = (p) => p.split(sep).join('/');

function classify(paths) {
  const out = { docs: [], notes: [], contracts: [], generated: [], source: [], config: [], other: [] };
  for (const p of paths) {
    if (p.startsWith('.agents/notes/') && p.endsWith('.md')) out.notes.push(p);
    else if (p.startsWith('docs/contracts/')) out.contracts.push(p);
    else if (p === 'dev/engineering/current-state.json' || p.startsWith('dev/engineering/')) out.generated.push(p);
    else if (p.endsWith('.md')) out.docs.push(p);
    // Source is source wherever it lives: package code outside src/ (shims, per-package
    // tests, manifests with logic) went to `other` before, so a change there produced no
    // owner-document advisory at all.
    else if (/^(packages|src)\/[\w./@-]+\.(?:ts|tsx|js|mjs|cjs|json)$/.test(p) || p.startsWith('scripts/')) out.source.push(p);
    else if (/(^|\/)(package\.json|tsconfig[^/]*\.json|cordis\.patch\.yml)$/.test(p) || p.startsWith('.github/')) out.config.push(p);
    else out.other.push(p);
  }
  return out;
}

export function probe(root, { base = null, worktreeOnly = false } = {}) {
  if (!existsSync(join(root, '.git')) && git(root, ['rev-parse', '--git-dir']) === null) {
    return { refused: 'NOT_A_GIT_REPO' };
  }
  const scope = worktreeOnly ? changeScope(root, null) : changeScope(root, base);
  if (scope.refused) return { refused: scope.refused };

  const buckets = classify(scope.all);
  let viewMirror = null; // graph#current_contract mirror, read-only, filled by the derived-view rule
  const commitExists = makeCommitExists(root);
  const findings = [];
  let shapes = { findings: [], applicable: false, coverage: null };
  const advisories = [];
  const selectedRules = [];

  // R1 notes (id / status-dir / reference / evidence integrity)
  if (buckets.notes.length) {
    selectedRules.push('agent-notes');
    const { findings: nf } = runNotes(root);
    for (const f of nf) findings.push({ code: `NOTE_${f.code}`, detail: f.detail });
  }

  // R2 links in changed markdown (and in any doc next to a changed note)
  const docTargets = [...new Set([...buckets.docs, ...buckets.notes, ...buckets.contracts, ...buckets.generated.filter((p) => p.endsWith('.md'))])];
  if (docTargets.length) {
    selectedRules.push('md-links');
    findings.push(...checkLinks(root, docTargets));
  }

  // R4 derived-view integrity: always run. It is a handful of git calls, and a
  // hand-edited or stale view is the highest-value drift this bridge prevents.
  {
    selectedRules.push('derived-view');
    const built = buildStateView(root);
    viewMirror = built.refused ? null : built.view.legacy_authority;
    if (built.refused) {
      // A missing or unreadable registry/view is never a green run: the probe would
      // otherwise report "no findings" exactly when the record it checks has gone.
      findings.push({ code: 'STATE_BRIDGE_UNAVAILABLE', detail: `derived view cannot be built (${built.refused}); a probe without registry + derived view cannot report green` });
    } else {
      findings.push(...built.findings.map((f) => ({ code: f.code, detail: f.detail })));
      const viewPath = join(root, 'dev/engineering/current-state.json');
      if (!existsSync(viewPath)) {
        findings.push({ code: 'STALE_GENERATED_VIEW', detail: 'dev/engineering/current-state.json is missing; run pnpm docs:sync --write' });
      } else if (readFileSync(viewPath, 'utf8') !== renderView(built)) {
        findings.push({ code: 'STALE_GENERATED_VIEW', detail: 'dev/engineering/current-state.json does not match registry+git; run pnpm docs:sync --write' });
      }
    }
  }

  // Contracts shape/field-set agreement. Unconditional, unlike the rules above: the two
  // copies of a frozen DTO live in packages/, which is outside every document bucket, so a
  // scope filter here would skip the check for precisely the changes it exists to catch --
  // and latent drift would pass the fast gate while failing the full one.
  selectedRules.push('contracts-shape');
  shapes = contractShapeFindings(root);
  findings.push(...shapes.findings);

  // R6 terminology, R7 claims-without-evidence (current-state docs only)
  if (docTargets.length || buckets.contracts.length) {
    selectedRules.push('terminology', 'claims-need-evidence');
    findings.push(...checkDeprecatedTerms(root, docTargets));
    findings.push(...checkClaimsHaveEvidence(root, docTargets, { commitExists }));
  }

  // R8 id uniqueness + contract anchors when the contract surface moved
  if (buckets.contracts.length || buckets.docs.some((d) => d === 'docs/glossary.md' || d === 'docs/terminology.md')) {
    selectedRules.push('id-uniqueness', 'contract-anchors');
    findings.push(...checkIdUniqueness(root));
    findings.push(...checkContractAnchors(root));
    findings.push(...checkRatification(root));
    const planDocs = docTargets.filter((d) => d.startsWith('docs/plans/'));
    const scanned = planDocs.length ? planDocs : allDocsForFullCheck(root).filter((d) => d.startsWith('docs/plans/'));
    const planCheck = checkPlanCitationBlocks(root, scanned, { mirror: viewMirror, commitExists });
    findings.push(...planCheck.findings);
    if (planCheck.declared === 0) {
      advisories.push({ code: 'PLAN_CITATION_ADOPTION', detail: 'no phase plan declares an eb-plan citation block yet; the interface exists and adoption is the phase owner decision — this line does not rewrite existing plans' });
    }
  }

  // R9 source change -> which owning document should be looked at (advisory in v0)
  if (buckets.source.length) {
    selectedRules.push('doc-ownership-impact');
    const ownership = selectOwningDocs(root, buckets.source, docTargets);
    findings.push(...ownership.findings);
    const staleOwners = ownership.owned.filter((o) => !o.touched);
    // A rule marked enforce:true is a promise this line made to itself: the tool and
    // the document describing it move together. Advisory would have been the honest
    // setting for somebody else's code; for our own tooling, a footnote nobody reads
    // is how a tool and its documentation drift apart — which is the exact failure
    // this whole branch exists to catch in other people's repos.
    const staleStrict = staleOwners.filter((o) => o.enforce);
    const strictSeen = new Set();
    for (const o of staleStrict) {
      if (strictSeen.has(o.source)) continue;
      strictSeen.add(o.source);
      findings.push({
        code: 'DOC_OWNER_UPDATE_MISSING',
        detail: `${o.source} changed but its declared owner document did not: ${o.docs.join(', ')} (rule enforce:true)`,
      });
    }
    if (ownership.owned.length) {
      advisories.push({
        code: 'DOC_IMPACT_OWNED',
        detail: `${ownership.owned.length} source path(s) have declared owner documents`,
        review_needed: staleOwners.map((o) => ({ source: o.source, docs: o.docs })),
      });
    }
    if (ownership.unowned.length) {
      advisories.push({
        code: 'DOC_IMPACT_UNOWNED',
        detail: `${ownership.unowned.length} source path(s) match no owner rule; coverage of dev/engineering/doc-ownership.yaml is ${ownership.owned.length}/${buckets.source.length}; e.g. ${ownership.unowned.slice(0, 4).join(', ')}`,
        candidates: ownership.unowned.slice(0, 12),
      });
    }
    advisories.push({
      code: 'SOURCE_CHANGED_DOC_IMPACT',
      detail: 'owning-document selection is advisory except where dev/engineering/doc-ownership.yaml marks a rule enforce:true; those are self-imposed refusals (DOC_OWNER_UPDATE_MISSING), and CI wiring (EB-ADR-0001) remains a separate coordination decision',
    });
  }

  const blocking = findings.filter((f) => BLOCKING.some((b) => f.code.startsWith(b)));
  const nonBlocking = findings.filter((f) => !BLOCKING.some((b) => f.code.startsWith(b)));
  return {
    base: base || '(worktree-only)',
    head: git(root, ['rev-parse', 'HEAD']),
    merge_base: scope.merge_base || null,
    changed: { total: scope.all.length, buckets },
    selected_rules: selectedRules,
    blocking,
    non_blocking: nonBlocking,
    shapes_applicable: shapes.applicable,
    shapes_compared: shapes.coverage ? shapes.coverage.pairs_compared : 0,
    advisories,
    limits: LIMITS,
  };
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  const args = process.argv.slice(2);
  const flagValue = (name) => {
    const i = args.indexOf(name);
    return i > -1 ? args[i + 1] : null;
  };
  const root = resolve(flagValue('--root') || resolve(dirname(fileURLToPath(import.meta.url)), '..'));
  const base = flagValue('--base');
  if (!base && !args.includes('--worktree-only')) {
    console.log('REFUSED BASE_REQUIRED: pass --base <verified-ref> or --worktree-only (a missing base is never treated as "no changes")');
    process.exit(2);
  }
  // A flag that is parsed and never read is worse than no flag: `--strict` was exactly
  // that, advertised by nothing and honoured by nothing, so `docs:probe --strict` reported
  // the ordinary verdict while pretending otherwise. Unknown flags are named and refused;
  // the CLI has no behaviour a typo can switch on.
  const known = new Set(['--root', '--base', '--worktree-only', '--json']);
  const unknown = args.filter((a) => a.startsWith('--') && !known.has(a));
  if (unknown.length) {
    console.log(`REFUSED UNKNOWN_FLAG: ${unknown.join(', ')} is not a flag of docs:probe (known: ${[...known].join(', ')})`);
    process.exit(2);
  }
  const result = probe(root, { base, worktreeOnly: args.includes('--worktree-only') });
  if (result.refused) {
    console.log(`REFUSED ${result.refused}`);
    process.exit(2);
  }
  if (args.includes('--json')) {
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log(`docs:probe base=${result.base} head=${String(result.head).slice(0, 9)} changed=${result.changed.total} rules=${result.selected_rules.join(',')}`);
    for (const f of result.blocking) console.log(`FAIL ${f.code}: ${f.detail}`);
    for (const f of result.non_blocking) console.log(`WARN ${f.code}: ${f.detail}`);
    for (const a of result.advisories) console.log(`ADVISORY ${a.code}: ${a.detail}`);
    for (const l of result.limits) console.log(`LIMIT ${l}`);
    console.log(`docs:probe blocking=${result.blocking.length} non_blocking=${result.non_blocking.length} advisories=${result.advisories.length} contracts=${result.shapes_applicable ? result.shapes_compared + ' pairs compared' : 'not applicable'}`);
  }
  process.exit(result.blocking.length ? 1 : 0);
}

#!/usr/bin/env node
// EB1-F docs:sync — complete document verification, and explicit regeneration
// (Engineering Baseline, first version).
//
//   pnpm docs:sync -- --check     read-only; CI uses only this mode
//   pnpm docs:sync -- --write     regenerate derived views, print the diff
//
// --write touches generated derivatives ONLY. Any target under a normative path
// (contracts, notes bodies, glossary, terminology, plans, active instructions) is
// REFUSED, so "make the check green by editing the contract" is not available
// through this tool. The legacy authority file (dev/agent-workflow/graph.yaml) is
// never a write target either.
//
// Exit codes: 0 ok | 1 findings | 2 REFUSED

import { existsSync, readFileSync } from 'node:fs';
import { checkGeneratedTarget, writeGenerated } from './generated-write.mjs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { run as runNotes } from './verify-agent-notes.mjs';
import { build as buildStateView, renderContractIndex, renderView, CATALOG_INDEX_PATH } from './gen-current-state.mjs';
import {
  makeCommitExists,
  checkLinks,
  checkDeprecatedTerms,
  checkClaimsHaveEvidence,
  checkIdUniqueness,
  checkContractAnchors,
  checkPlanCitationBlocks,
  isBlockingFinding,
  SELF_UPDATE_CODES,
  contractShapeFindings,
  checkRatification,
  allDocsForFullCheck,
} from './doc-checks.mjs';

// Both entries are full paths, and both are mirrored in generated-write.mjs's
// GENERATED_FILES. Adding an area there is not enough to reach a file, and adding a path
// here is not enough either: the write goes through checkGeneratedTarget, which demands
// both lists. That is why ids.yaml, README.md and promotion-rules.md sit inside a named
// area and are still not writable.
const GENERATED_ALLOW_LIST = [
  'dev/engineering/current-state.json',
  CATALOG_INDEX_PATH,
];
const NORMATIVE_PREFIXES = [
  'docs/contracts/', 'docs/plans/', '.agents/notes/', 'dev/agent-workflow/',
  'docs/glossary.md', 'docs/terminology.md', 'docs/STATUS.md', 'AGENTS.md',
];

export function isWriteAllowed(rel) {
  if (GENERATED_ALLOW_LIST.includes(rel)) return true;
  if (NORMATIVE_PREFIXES.some((p) => rel === p || rel.startsWith(p))) return false;
  return false; // anything else is not a known derivative
}

export function check(root) {
  const commitExists = makeCommitExists(root);
  const findings = [];
  const notes = runNotes(root);
  for (const f of notes.findings) findings.push({ code: `NOTE_${f.code}`, detail: f.detail });

  const docs = allDocsForFullCheck(root);
  findings.push(...checkLinks(root, docs));
  findings.push(...checkIdUniqueness(root));
  findings.push(...checkContractAnchors(root));
  findings.push(...checkDeprecatedTerms(root, docs));
  findings.push(...checkClaimsHaveEvidence(root, docs, { commitExists }));

  findings.push(...checkRatification(root));
  const built = buildStateView(root);
  if (built.refused) {
    findings.push({ code: 'DERIVED_VIEW_UNAVAILABLE', detail: built.refused });
  } else {
    findings.push(...built.findings);
    const viewPath = join(root, 'dev/engineering/current-state.json');
    const rendered = renderView(built);
    if (!existsSync(viewPath)) findings.push({ code: 'STALE_GENERATED_VIEW', detail: 'missing; run --write' });
    else if (readFileSync(viewPath, 'utf8') !== rendered) findings.push({ code: 'STALE_GENERATED_VIEW', detail: 'out of date; run --write' });
  }
  const planDocs = docs.filter((d) => d.startsWith('docs/plans/'));
  const planCheck = checkPlanCitationBlocks(root, planDocs, { mirror: built.refused ? null : built.view.legacy_authority, commitExists });
  findings.push(...planCheck.findings);
  // The contracts shape check runs here as well as in its own CLI. Standalone output is a
  // report; a finding that never reaches a gate is how a checked rule quietly stops being
  // true without anyone deciding to stop checking it.
  const shapes = contractShapeFindings(root);
  findings.push(...shapes.findings);
  return {
    findings,
    docs: docs.length,
    notes: notes.checked,
    plans_scanned: planDocs.length,
    plans_declaring: planCheck.declared,
    shapes_applicable: shapes.applicable,
    shapes_compared: shapes.coverage ? shapes.coverage.pairs_compared : 0,
  };
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  const args = process.argv.slice(2);
  const root = (() => {
    const i = args.indexOf('--root');
    return i > -1 ? resolve(args[i + 1]) : resolve(dirname(fileURLToPath(import.meta.url)), '..');
  })();
  const write = args.includes('--write');
  const checkMode = args.includes('--check');
  if (!write && !checkMode) {
    console.error('usage: docs-sync.mjs --check | --write [--root <dir>]');
    process.exit(2);
  }

  if (write) {
    const built = buildStateView(root);
    if (built.refused) {
      console.log(`REFUSED ${built.refused}`);
      process.exit(2);
    }
    // The derived view is a record OF the registry. Writing it while the registry
    // fails its own integrity rules would launder the defect into a generated file
    // that reads like a verified statement.
    // Same classification as docs:sync --check and docs:probe: a claim that cites
    // nothing must not be writable by one entry point and only warned about by another.
    // A derivative is a record OF its inputs, so writing one while its inputs fail
    // their own integrity rules would launder the defect into a file that reads like a
    // verified statement. Classification is shared with --check and docs:probe.
    // One carve-out, named: the freshness of the files this command owns may be
    // repaired by this command. Refusing on STALE_GENERATED_* would block the very
    // regeneration that fixes them. Everything else still refuses.
    const blocking = built.findings.filter((f) => isBlockingFinding(f) && !SELF_UPDATE_CODES.includes(f.code));
    if (blocking.length) {
      for (const f of blocking) console.log(`FAIL ${f.code}: ${f.detail}`);
      console.log('REFUSED write: findings above');
      process.exit(1);
    }
    const DERIVATIVES = [
      { path: 'dev/engineering/current-state.json', render: () => renderView(built) },
      { path: CATALOG_INDEX_PATH, render: () => renderContractIndex(root) },
    ];
    const actions = [];
    for (const d of DERIVATIVES) {
      if (!isWriteAllowed(d.path)) {
        console.log(`REFUSED WRITE_TARGET_NORMATIVE: ${d.path}`);
        process.exit(2);
      }
      // Boundary BEFORE content. Comparing first let a symlinked target answer
      // "already fresh" and exit 0 without the location ever being checked — found by
      // NEG-27 rather than by reading, which is the point of the control.
      const place = checkGeneratedTarget(root, d.path);
      if (!place.ok) {
        console.log(`REFUSED WRITE_BOUNDARY: ${place.why}`);
        process.exit(2);
      }
      const next = d.render();
      const before = existsSync(join(root, d.path)) ? readFileSync(join(root, d.path), 'utf8') : '';
      if (before === next) {
        // Wording matters: this states content equality and that no bytes were
        // written. It is not a claim that a write was verified safe.
        actions.push(`no-op ${d.path} (bytes already match the rendered output; nothing written)`);
        continue;
      }
      const written = writeGenerated(root, d.path, next);
      if (!written.ok) {
        console.log(`REFUSED WRITE_BOUNDARY: ${written.why}`);
        process.exit(2);
      }
      // "1 -> 153 lines" would imply a one-line file existed. Report creation as
      // creation: an absent target has no line count.
      const from = before === '' ? 'absent' : `${before.split('\n').length} lines`;
      actions.push(`regenerated ${d.path} (${from} -> ${next.split('\n').length} lines)`);
    }
    console.log(`docs:sync --write: ${actions.join('; ')}; normative files untouched`);
    process.exit(0);
  }

  const result = check(root);
  // One finding set, one definition of a refusal, shared with docs:probe and the --write
  // gate. --check used to exit 1 on any finding whatsoever, so a fact worth recording
  // that is not a refusal (a derivative not generated yet) failed the check while the
  // probe called the same input non-blocking. Two tools disagreeing about one input is
  // worse than either verdict alone, so the classification is now the same everywhere.
  const blocking = result.findings.filter(isBlockingFinding);
  for (const f of result.findings) console.log(`${isBlockingFinding(f) ? 'FAIL' : 'WARN'} ${f.code}: ${f.detail}`);
  console.log(`docs:sync --check: docs=${result.docs} notes=${result.notes} plans=${result.plans_scanned}(${result.plans_declaring} declaring) findings=${result.findings.length} blocking=${blocking.length} contracts=${result.shapes_applicable ? result.shapes_compared + ' pairs compared' : 'not applicable'}`);
  console.log('LIMIT complete static check: no C1/C2/C3, no security negative, no runtime behaviour proof');
  process.exit(blocking.length ? 1 : 0);
}

#!/usr/bin/env node
// EB1-C state derivation bridge (Engineering Baseline, first version).
//
//   node scripts/gen-current-state.mjs --write    regenerate dev/engineering/current-state.json
//   node scripts/gen-current-state.mjs --check    fail if the committed view is stale or a claim is fake
//
// Pure Node + read-only git. No dependency, no wall-clock timestamp in the
// output (so --check is byte-reproducible), and no write path to any file other
// than the generated view named in the registry. The legacy authority
// (dev/agent-workflow/graph.yaml#current_contract) is read and mirrored only.
//
// Exit codes: 0 ok | 1 findings (stale view, schema violation, FAKE_VERIFICATION)
//             | 2 REFUSED (unusable input: no registry, not a git repo)

import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { writeGenerated } from './generated-write.mjs';
import { join, resolve, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
// One blocking classification for all three entry points; doc-checks owns the list and
// does not import this file, so the dependency stays one-directional.
import { isBlockingFinding, SELF_UPDATE_CODES } from './doc-checks.mjs';

export const ENUMS = {
  decision_status: ['proposed', 'accepted', 'rejected', 'superseded', 'pending_coordination'],
  implementation_status: ['not_started', 'in_progress', 'implemented_in_branch', 'merged'],
  verification_status: ['not_verified', 'verified_local', 'verified_ci', 'verified_host'],
  release_status: ['not_released', 'candidate', 'released'],
};
const KINDS = ['work-package', 'implementation-pr', 'gate', 'migration'];
const REQUIRED = ['id', 'kind', 'title', 'decision_status', 'implementation_status', 'verification_status', 'release_status', 'owners'];
// Closed field set. registry.schema.json says additionalProperties:false; before this
// rule nothing enforced it, so a typo'd field silently carried no meaning.
const KNOWN_FIELDS = [...REQUIRED, 'refs', 'verification_artifacts', 'verified_tier', 'verification_commit', 'merged_commit'];
const ID_RE = /^EB[0-9]-[A-Z0-9-]+$/;
// Evidence tier of a claim: which environment it was earned in. Named once so the
// validator and the schema cross-check below read the same list.
const TIERS = ['C1', 'C2', 'C3'];
const SCHEMA_PATH = 'dev/engineering/registry.schema.json';
// A claim commit has to name a commit object, so abbreviated hex is not enough here;
// 40 hex is what the checks below enforce. COMMIT_REX is used by those checks and
// COMMIT_RE is the same rule as a source string for the schema comparison, so there
// is no second, drifting definition of what a commit field must look like.
const COMMIT_REX = /^[0-9a-f]{40}$/;
const COMMIT_RE = COMMIT_REX.source;

function git(root, args) {
  try {
    return execFileSync('git', ['-C', root, ...args], { encoding: 'utf8' }).trim();
  } catch {
    return null;
  }
}

function unquote(s) {
  return String(s).replace(/^['"]|['"]$/g, '').trim();
}

/** Parse the strict registry subset: top-level scalars + an `entries:` list of flat maps. */
export function parseRegistryStrict(text) {
  const doc = { entries: [] };
  const errors = [];
  const keysSeen = new WeakMap(); // a repeated key in one mapping is a defect, not last-write-wins
  const seenTop = new Set(); // top-level keys already assigned, including `entries`
  const lines = text.split(/\r?\n/);
  let cur = null;
  let entryIndent = null; // column of the current entry's "-"
  let fieldIndent = null; // column of the current entry's fields
  let pendingList = null; // {obj, key, itemIndent}
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    if (!raw.trim() || raw.trimStart().startsWith('#')) continue;
    const indent = raw.length - raw.trimStart().length;
    const trimmed = raw.trim();

    const blockItem = trimmed.match(/^-\s+(.*)$/);
    if (blockItem && pendingList && indent === pendingList.itemIndent) {
      pendingList.obj[pendingList.key].push(unquote(blockItem[1]));
      continue;
    }
    pendingList = null;

    const entryStart = trimmed.match(/^-\s+(\w+):\s*(.*)$/);
    const isEntry = Boolean(entryStart) && (entryIndent === null || indent === entryIndent);
    const field = trimmed.match(/^(\w+):\s*(.*)$/);

    let target = null;
    let key = null;
    let value = null;
    if (isEntry) {
      if (cur === null) entryIndent = indent;
      cur = {};
      doc.entries.push(cur);
      fieldIndent = indent + 2;
      target = cur;
      key = entryStart[1];
      value = entryStart[2].trim();
    } else if (field && cur && indent >= fieldIndent) {
      target = cur;
      key = field[1];
      value = field[2].trim();
    } else if (field && entryIndent === null) {
      if (field[1] === 'entries') {
        // Same class as the other duplicate-key refusal, and the same silent-loss
        // bug: a second top-level entries: restarted the list, so the first block
        // of records disappeared from the view without any complaint.
        if (seenTop.has('entries')) errors.push(`registry-duplicate-key:L${i + 1}:entries`);
        seenTop.add('entries');
        continue;
      }
      // A repeated top-level key used to overwrite silently, so a registry carrying two
      // legacy_execution_authority lines kept whichever came last.
      if (Object.prototype.hasOwnProperty.call(doc, field[1])) errors.push(`registry-duplicate-key:L${i + 1}:${field[1]}`);
      doc[field[1]] = unquote(field[2]);
      continue;
    } else {
      errors.push(`registry-unsupported-syntax:L${i + 1}:${trimmed}`);
      continue;
    }
    let seen = keysSeen.get(target);
    if (!seen) { seen = new Set(); keysSeen.set(target, seen); }
    if (seen.has(key)) errors.push(`registry-duplicate-key:L${i + 1}:${key}`);
    seen.add(key);
    if (value === '') {
      target[key] = [];
      pendingList = { obj: target, key, itemIndent: indent + 2 };
    } else if (value.startsWith('[') && value.endsWith(']')) {
      const inner = value.slice(1, -1).trim();
      target[key] = inner ? inner.split(',').map((s) => unquote(s.trim())) : [];
    } else {
      target[key] = unquote(value);
    }
  }
  return { doc, errors };
}

const ID_REF_RE = /^(REQ|INV|AC|IDEA)-EB-[A-Z0-9-]+$|^EB-ADR-\d{4}$/;
const EVIDENCE_ROOTS = ['dev/agent-workflow/evidence/'];
const ARTIFACT_EXT = /\.(log|txt|md|json|jsonl|csv)$/i;

/** Ids that actually exist: the contract index plus every agent note in any lifecycle
 *  directory. Answering "does this cited id resolve?" is all it is used for. */
function knownContractIds(root) {
  const ids = new Set();
  const index = join(root, 'docs/contracts/engineering-baseline/ids.yaml');
  if (existsSync(index)) {
    for (const m of readFileSync(index, 'utf8').matchAll(/^\s*-?\s*id:\s*([A-Z]+-EB-[A-Z0-9-]+)/gm)) ids.add(m[1]);
  }
  for (const dir of ['proposed', 'implemented', 'rejected', 'archived']) {
    const d = join(root, '.agents/notes', dir);
    if (!existsSync(d)) continue;
    for (const name of readdirSync(d)) {
      if (!name.endsWith('.md')) continue;
      const m = readFileSync(join(d, name), 'utf8').match(/^id:\s*(\S+)\s*$/m);
      if (m) ids.add(m[1]);
    }
  }
  return ids;
}

export function validateRegistry(doc, root) {
  const findings = [];
  if (doc.schema_version === undefined) findings.push({ code: 'REGISTRY_SCHEMA', detail: 'schema_version missing' });
  else if (Number(doc.schema_version) !== 1) findings.push({ code: 'REGISTRY_SCHEMA', detail: `schema_version=${doc.schema_version} (expected 1)` });
  if (!doc.entries.length) findings.push({ code: 'REGISTRY_SCHEMA', detail: 'no entries' });
  const seen = new Set();
  for (const e of doc.entries) {
    const id = String(e.id || '<no-id>');
    for (const key of Object.keys(e)) {
      if (!KNOWN_FIELDS.includes(key)) {
        findings.push({ code: 'REGISTRY_UNKNOWN_FIELD', detail: `${id}: ${key} is not a field of the registry subset (typo or unsupported extension)` });
      }
    }
    for (const key of REQUIRED) {
      if (e[key] === undefined || e[key] === '' || (Array.isArray(e[key]) && e[key].length === 0 && key !== 'refs')) {
        findings.push({ code: 'REGISTRY_SCHEMA', detail: `${id}: required field ${key} missing or empty` });
      }
    }
    if (!ID_RE.test(id)) findings.push({ code: 'REGISTRY_SCHEMA', detail: `${id}: id grammar` });
    if (seen.has(id)) findings.push({ code: 'REGISTRY_DUP_ID', detail: id });
    seen.add(id);
    if (!KINDS.includes(e.kind)) findings.push({ code: 'REGISTRY_SCHEMA', detail: `${id}: kind=${e.kind}` });
    for (const [axis, allowed] of Object.entries(ENUMS)) {
      if (e[axis] !== undefined && !allowed.includes(e[axis])) {
        findings.push({ code: 'REGISTRY_AXIS', detail: `${id}: ${axis}=${e[axis]} not in ${allowed.join('|')}` });
      }
    }
    const artifacts = Array.isArray(e.verification_artifacts) ? e.verification_artifacts : [];
    if (e.verification_artifacts !== undefined && !Array.isArray(e.verification_artifacts)) {
      findings.push({ code: 'REGISTRY_ARTIFACTS_TYPE', detail: `${id}: verification_artifacts must be a list` });
    }
    if (e.owners !== undefined && !Array.isArray(e.owners)) {
      findings.push({ code: 'REGISTRY_OWNER_TYPE', detail: `${id}: owners must be a list of accountable roles, got ${typeof e.owners}` });
    }
    for (const p of artifacts) {
      if (typeof p !== 'string' || !EVIDENCE_ROOTS.some((r) => p.startsWith(r))) {
        findings.push({ code: 'ARTIFACT_LOCATION_UNCONTROLLED', detail: `${id}: ${p} must live under ${EVIDENCE_ROOTS.join(' or ')}: a verification artifact is a kept record, not an inline assertion` });
      } else if (!ARTIFACT_EXT.test(p)) {
        findings.push({ code: 'ARTIFACT_TYPE_UNSUPPORTED', detail: `${id}: ${p} (supported: log, txt, md, json, jsonl, csv)` });
      }
    }
    const claimsVerified = String(e.verification_status || '').startsWith('verified');
    if (claimsVerified) {
      const present = artifacts.filter((p) => existsSync(join(root, p)));
      if (present.length === 0) {
        findings.push({ code: 'FAKE_VERIFICATION', detail: `${id}: verification_status=${e.verification_status} with no existing artifact (refused; INV-EB-0009)` });
      }
      for (const p of artifacts) {
        if (!existsSync(join(root, p))) findings.push({ code: 'ARTIFACT_MISSING', detail: `${id}: ${p}` });
      }
    }
    // A delivery claim has to be bound to metadata that already exists outside this
    // file: a commit object in this repository, and for merge/release claims, actual
    // ancestry in origin/master. This is not a proof system — it refuses claims that
    // cite nothing, which is the exact hole where "verified_host" could be typed into
    // a YAML file next to a C1 log and read as real-environment evidence.
    const tier = e.verified_tier;
    if (tier !== undefined && !TIERS.includes(tier)) {
      findings.push({ code: 'CLAIM_TIER_UNKNOWN', detail: `${id}: verified_tier=${tier} (expected C1|C2|C3)` });
    }
    if (claimsVerified && e.verification_status !== 'verified_local') {
      const commit = String(e.verification_commit || '');
      if (!COMMIT_REX.test(commit)) {
        findings.push({ code: 'CLAIM_UNBOUND', detail: `${id}: ${e.verification_status} requires verification_commit (40-hex); local work must stay verified_local` });
      } else if (git(root, ['cat-file', '-t', commit]) !== 'commit') {
        findings.push({ code: 'CLAIM_UNBOUND', detail: `${id}: verification_commit ${commit} is not a commit in this repository` });
      }
    }
    if (claimsVerified && e.verification_status === 'verified_host') {
      if (tier === 'C1') {
        findings.push({ code: 'CLAIM_TIER_MISMATCH', detail: `${id}: verified_host asserts real-environment behaviour; C1 static/local evidence cannot stand in for it` });
      } else if (tier !== 'C2' && tier !== 'C3') {
        findings.push({ code: 'CLAIM_TIER_MISSING', detail: `${id}: verified_host requires verified_tier C2 or C3` });
      }
    }
    if (e.implementation_status === 'merged') {
      const mc = String(e.merged_commit || e.verification_commit || '');
      const ok = COMMIT_REX.test(mc) && git(root, ['cat-file', '-t', mc]) === 'commit' && git(root, ['merge-base', '--is-ancestor', mc, 'origin/master']) !== null;
      if (!ok) findings.push({ code: 'MERGED_CLAIM_UNCORROBORATED', detail: `${id}: implementation_status=merged needs merged_commit that exists and is an ancestor of origin/master` });
    }
    if (e.release_status === 'candidate' || e.release_status === 'released') {
      const needed = e.release_status === 'released' ? ['C3'] : ['C2', 'C3'];
      const hostVerified = e.verification_status === 'verified_host' && needed.includes(tier);
      const merged = git(root, ['merge-base', '--is-ancestor', 'HEAD', 'origin/master']) !== null;
      if (!hostVerified || !merged) {
        findings.push({ code: 'RELEASE_CLAIM_UNCORROBORATED', detail: `${id}: release_status=${e.release_status} requires verified_host at ${needed.join('/')} plus a head that is an ancestor of origin/master` });
      }
    }
    const refs = Array.isArray(e.refs) ? e.refs : [];
    if (typeof e.refs === 'string' && e.refs) {
      findings.push({ code: 'REGISTRY_REF_SCALAR', detail: `${id}: refs must be a list, got scalar "${e.refs}"` });
      refs.push(e.refs);
    } else if (e.refs !== undefined && !Array.isArray(e.refs)) {
      // Before this, a scalar string was refused and anything else non-list (a mapping,
      // a number) was silently read as "no refs", which meant the documented
      // type: array was only half enforced -- the most convincing kind of gap, because
      // the common mistake was caught and the uncommon one became an absence.
      findings.push({ code: 'REGISTRY_REF_TYPE', detail: `${id}: refs must be a list, got ${typeof e.refs}` });
    }
    const knownIds = knownContractIds(root);
    for (const ref of refs) {
      if (typeof ref !== 'string' || !ref.trim()) {
        findings.push({ code: 'REGISTRY_REF_TYPE', detail: `${id}: every ref must be a non-empty string` });
        continue;
      }
      if (ID_REF_RE.test(ref)) {
        if (!knownIds.has(ref)) {
          findings.push({ code: 'REGISTRY_REF_UNRESOLVED', detail: `${id}: ${ref} has id grammar but is declared nowhere (ids.yaml or an agent note)` });
        }
        continue;
      }
      if (!existsSync(join(root, ref))) findings.push({ code: 'REF_MISSING', detail: `${id}: ${ref}` });
    }
  }
  return findings;
}

function readLegacyAuthority(root) {
  const file = join(root, 'dev/agent-workflow/graph.yaml');
  if (!existsSync(file)) return { present: false };
  const text = readFileSync(file, 'utf8');
  const block = text.match(/\ncurrent_contract:\n((?:[ ]{2}\w+:.*\n?)+)/);
  const pick = (key) => {
    const m = block ? block[1].match(new RegExp(`^  ${key}:\\s*(\\S+)`, 'm')) : null;
    return m ? m[1].replace(/^"|"$/g, '') : null;
  };
  const baseline = pick('baseline');
  return {
    present: true,
    file: relative(root, file),
    phase_id: pick('phase_id'),
    active_plan: pick('active_plan'),
    baseline,
    baseline_exists: baseline ? git(root, ['cat-file', '-t', baseline]) === 'commit' : false,
    baseline_is_ancestor_of_head: baseline ? git(root, ['merge-base', '--is-ancestor', baseline, 'HEAD']) !== null : false,
    note: 'read-only mirror; this generator never writes graph.yaml and does not become an execution authority',
  };
}

/** Compare the descriptive schema against the rules this file enforces. Only the
 *  keywords that schema actually uses are interpreted — required, enum, pattern,
 *  additionalProperties — so this is a comparison, not a half-written validator, and
 *  the validator stays the authority. Without it the two drift silently: the schema
 *  has in turn promised a closed field set nobody enforced, listed `refs` as required,
 *  and given `verified_tier` the verification_status values instead of C1|C2|C3. */
export function checkSchemaAgreement(root) {
  const file = join(root, SCHEMA_PATH);
  if (!existsSync(file)) {
    return [{ code: 'SCHEMA_MISSING', detail: SCHEMA_PATH + ' is gone, so the documented shape can no longer be compared with the enforced one' }];
  }
  let doc;
  try { doc = JSON.parse(readFileSync(file, 'utf8')); }
  catch (e) { return [{ code: 'SCHEMA_UNPARSEABLE', detail: SCHEMA_PATH + ': ' + ((e && e.message) || String(e)) }]; }
  const item = (((doc.properties || {}).entries || {}).items || {});
  const props = item.properties || {};
  const out = [];
  const same = (a, b) => a.length === b.length && a.every((x, i) => x === b[i]);
  const req = item.required || [];
  if (!same([...req].sort(), [...REQUIRED].sort())) {
    out.push({ code: 'SCHEMA_REQUIRED_MISMATCH', detail: 'schema required=[' + req.join(',') + '] enforced=[' + REQUIRED.join(',') + ']' });
  }
  for (const k of KNOWN_FIELDS) if (!props[k]) out.push({ code: 'SCHEMA_FIELD_MISSING', detail: k + ' is enforced but absent from ' + SCHEMA_PATH });
  for (const k of Object.keys(props)) if (!KNOWN_FIELDS.includes(k)) out.push({ code: 'SCHEMA_FIELD_EXTRA', detail: k + ' is documented but the validator does not accept it' });
  const wantEnum = Object.assign({ kind: KINDS, verified_tier: TIERS }, ENUMS);
  for (const k of Object.keys(wantEnum)) {
    const got = props[k] && props[k].enum;
    if (!got) {
      // Silence is not agreement: the comparison only ran when the keyword existed, so
      // a schema that said nothing about the vocabulary passed a validator that enforces one.
      out.push({ code: 'SCHEMA_KEYWORD_MISSING', detail: k + ': ' + SCHEMA_PATH + ' states no enum, but the value set is enforced [' + wantEnum[k].join(',') + ']' });
      continue;
    }
    if (!same([...got].sort(), [...wantEnum[k]].sort())) {
      out.push({ code: 'SCHEMA_ENUM_MISMATCH', detail: k + ': schema=[' + got.join(',') + '] enforced=[' + wantEnum[k].join(',') + ']' });
    }
  }
  const wantPattern = { id: ID_RE.source, verification_commit: COMMIT_RE, merged_commit: COMMIT_RE };
  for (const k of Object.keys(wantPattern)) {
    const got = props[k] && props[k].pattern;
    if (!got) out.push({ code: 'SCHEMA_KEYWORD_MISSING', detail: k + ': ' + SCHEMA_PATH + ' states no pattern, but /' + wantPattern[k] + '/ is enforced' });
    else if (got !== wantPattern[k]) out.push({ code: 'SCHEMA_PATTERN_MISMATCH', detail: k + ': schema=/' + got + '/ enforced=/' + wantPattern[k] + '/' });
  }
  // type / minItems, and only where a rule actually refuses. A keyword nothing enforces
  // is documentation; comparing it would be theatre. Each expectation below names the
  // enforcing finding in the comment next to it.
  const entriesNode = ((doc.properties || {}).entries) || {};
  const expectType = (node, label, want, enforcedBy) => {
    if (!node || typeof node !== 'object') return; // a whole absent field is SCHEMA_FIELD_MISSING
    const got = node.type;
    if (got === undefined) out.push({ code: 'SCHEMA_TYPE_MISSING', detail: `${label}: schema states no type, but ${enforcedBy} refuses anything that is not ${want}` });
    else if (got !== want) out.push({ code: 'SCHEMA_TYPE_MISMATCH', detail: `${label}: schema type=${got} enforced=${want} (${enforcedBy})` });
  };
  const expectMinItems = (node, label, want, enforcedBy) => {
    if (!node || typeof node !== 'object') return;
    const got = node.minItems;
    if (got === undefined) out.push({ code: 'SCHEMA_MINITEMS_MISSING', detail: `${label}: schema sets no minItems, but ${enforcedBy} refuses an empty list` });
    else if (got !== want) out.push({ code: 'SCHEMA_MINITEMS_MISMATCH', detail: `${label}: schema minItems=${got} enforced=${want} (${enforcedBy})` });
  };
  expectType(entriesNode, 'entries', 'array', 'the parser yields a list or refuses');
  expectType(props.owners, 'entry.owners', 'array', 'REGISTRY_OWNER_TYPE');
  expectType(props.refs, 'entry.refs', 'array', 'REGISTRY_REF_SCALAR / REGISTRY_REF_TYPE');
  expectType(props.verification_artifacts, 'entry.verification_artifacts', 'array', 'REGISTRY_ARTIFACTS_TYPE');
  expectMinItems(entriesNode, 'entries', 1, "validateRegistry's 'no entries' rule");
  expectMinItems(props.owners, 'entry.owners', 1, 'the required-field rule, which treats an empty list as absent');
  // The opposite direction matters as much: `refs` is the one list the required-field
  // rule names as allowed to be empty, so a schema claiming a positive floor there would
  // forbid something the validator permits -- drift in the strict direction is still
  // drift. Only a positive floor counts: `minItems: 0` says exactly what the validator
  // already allows, and refusing it would be inventing a violation to look thorough.
  if (props.refs && typeof props.refs === 'object' && Number(props.refs.minItems) > 0) {
    out.push({ code: 'SCHEMA_MINITEMS_UNEXPECTED', detail: `entry.refs: schema says minItems=${props.refs.minItems}, but the required-field rule explicitly allows an empty refs list` });
  }
  // Every artifact path goes through `typeof p !== 'string'`, so the element type is
  // enforced even though it sits one level deeper than the field itself.
  const artifactItems = props.verification_artifacts && props.verification_artifacts.items;
  if (!artifactItems || typeof artifactItems === 'object' && artifactItems.type === undefined) {
    out.push({ code: 'SCHEMA_KEYWORD_MISSING', detail: 'entry.verification_artifacts.items: schema states no type, but each path is checked with typeof p === "string" (ARTIFACT_LOCATION_UNCONTROLLED)' });
  } else if (artifactItems.type !== 'string') {
    out.push({ code: 'SCHEMA_TYPE_MISMATCH', detail: `entry.verification_artifacts.items: schema type=${artifactItems.type} enforced=string (ARTIFACT_LOCATION_UNCONTROLLED)` });
  }
  if (item.additionalProperties !== false) {
    out.push({ code: 'SCHEMA_CONSTRAINT_MISMATCH', detail: SCHEMA_PATH + ' does not say additionalProperties:false, yet the entry field set is closed (REGISTRY_UNKNOWN_FIELD)' });
  }
  return out;
}

export function build(root) {
  const registryFile = join(root, 'dev/engineering/registry.yaml');
  if (!existsSync(registryFile)) return { refused: 'REGISTRY_MISSING' };
  if (git(root, ['rev-parse', '--git-dir']) === null) return { refused: 'NOT_A_GIT_REPO' };
  const { doc, errors } = parseRegistryStrict(readFileSync(registryFile, 'utf8'));
  const findings = errors.map((e) => ({ code: 'REGISTRY_PARSE', detail: e }));
  findings.push(...validateRegistry(doc, root));
  findings.push(...checkSchemaAgreement(root));
  findings.push(...checkContractIndex(root));

  const dirty = (git(root, ['status', '--porcelain']) || '').split('\n').filter(Boolean);
  // The persisted view carries ONLY facts that are stable between commits. Live
  // Git state (branch, head, dirtiness) is returned separately as `runtime` and
  // printed by --check / the probe: embedding it here would make the committed
  // view stale on every commit and turn a drift signal into churn.
  const view = {
    generated_by: 'scripts/gen-current-state.mjs',
    schema_version: 1,
    source_registry: 'dev/engineering/registry.yaml',
    source_registry_sha: git(root, ['hash-object', 'dev/engineering/registry.yaml']),
    // The view is also read against the id catalog — every `refs` entry resolves
    // through ids.yaml — so it names that input as well. Before this, an edit to
    // ids.yaml left the view reporting itself "fresh" while the meaning of every ref in
    // it had moved: freshness was being claimed about one of two inputs. A catalog edit
    // now has to be followed by a regeneration, which is what the field is for.
    source_catalog: 'docs/contracts/engineering-baseline/ids.yaml',
    source_catalog_sha: git(root, ['hash-object', 'docs/contracts/engineering-baseline/ids.yaml']),
    axes_legend: ENUMS,
    legacy_authority: readLegacyAuthority(root),
    entries: doc.entries.map((e) => {
      const artifacts = Array.isArray(e.verification_artifacts) ? e.verification_artifacts : [];
      return {
        id: e.id,
        kind: e.kind,
        title: e.title,
        decision_status: e.decision_status,
        implementation_status: e.implementation_status,
        verification_status: e.verification_status,
        release_status: e.release_status,
        owners: e.owners,
        refs: e.refs,
        verification: {
          claimed: String(e.verification_status || '').startsWith('verified'),
          artifacts: artifacts.map((p) => ({ path: p, exists: existsSync(join(root, p)) })),
        },
      };
    }),
  };
  return {
    view,
    findings,
    runtime: {
      branch: git(root, ['rev-parse', '--abbrev-ref', 'HEAD']),
      head: git(root, ['rev-parse', 'HEAD']),
      merge_base_with_master: git(root, ['merge-base', 'HEAD', 'origin/master']),
      merged_into_master: git(root, ['merge-base', '--is-ancestor', 'HEAD', 'origin/master']) !== null,
      dirty_paths: dirty.length,
    },
    topLevel: { migration_of_legacy_consumers: doc.migration_of_legacy_consumers, legacy_execution_authority: doc.legacy_execution_authority },
  };
}

/** The one canonical serialization of the persisted view. probe, sync and the
 *  controls all compare against this, so they cannot disagree about "fresh". */
export function renderView(built) {
  return `${JSON.stringify({ ...built.view, migration: { migration_of_legacy_consumers: built.topLevel.migration_of_legacy_consumers, legacy_execution_authority: built.topLevel.legacy_execution_authority } }, null, 2)}\n`;
}

/**
 * The second derived artifact: a readable index over the id catalog. Reported here, and
 * written only through scripts/generated-write.mjs like every other derivative.
 *
 * Why: ids.yaml is machine-readable and nobody reads it, so the ids that plans and notes
 * are supposed to cite had no browsable listing — the contract index in that directory
 * carried zero rows for 19 catalog entries. A hand-kept copy would be the same drift in
 * a new place, so this is generated, and the check below is what keeps it honest.
 *
 * The write surface is deliberately NOT widened by this file alone: adding the path to
 * GENERATED_FILES / the docs:sync allow-list is the approval step, and until then the
 * check reports CATALOG_NOT_GENERATED (non-blocking) instead of writing anything.
 */
export const CATALOG_INDEX_PATH = 'docs/contracts/engineering-baseline/INDEX.md';
export const CATALOG_SOURCE_PATH = 'docs/contracts/engineering-baseline/ids.yaml';

export function parseContractCatalog(root) {
  const file = join(root, CATALOG_SOURCE_PATH);
  if (!existsSync(file)) return null;
  const entries = [];
  let cur = null;
  readFileSync(file, 'utf8').split(/\r?\n/).forEach((line) => {
    if (!line.trim() || line.trimStart().startsWith('#')) return;
    const id = line.match(/^\s*- id:\s*(.+)$/);
    if (id) { cur = { id: unquote(id[1]) }; entries.push(cur); return; }
    if (!cur) return;
    const f = line.match(/^\s+([a-z_]+):\s*(.*)$/);
    if (!f) return;
    const value = f[2].trim();
    cur[f[1]] = value.startsWith('[') ? value.slice(1, -1).split(',').map(unquote).filter(Boolean) : unquote(value);
  });
  return entries;
}

export function renderContractIndex(root) {
  const entries = parseContractCatalog(root) || [];
  const byKind = {};
  for (const e of entries) (byKind[e.kind || 'unclassified'] = byKind[e.kind || 'unclassified'] || []).push(e);
  const out = [
    '<!-- GENERATED FILE - do not edit. Rendered from docs/contracts/engineering-baseline/ids.yaml',
    '     by scripts/gen-current-state.mjs; refresh with `node scripts/docs-sync.mjs --write`.',
    '     docs:sync --check and docs:probe refuse when this file no longer matches the catalog. -->',
    '',
    `# Engineering Baseline id index (${entries.length} ids)`,
    '',
    'Browsable listing over the machine-readable catalog. `ids.yaml` stays the source of',
    'truth; this file exists so the ids can be read and cited without opening YAML.',
    'Listing an id here grants it nothing: every entry stays',
    '`proposed-not-ratified` until an approval is recorded in',
    '`dev/engineering/registry.yaml` and the Contract Owner has reviewed it.',
    '',
  ];
  for (const kind of Object.keys(byKind).sort()) {
    out.push(`## ${kind} (${byKind[kind].length})`, '');
    for (const e of byKind[kind].slice().sort((a, b) => (a.id < b.id ? -1 : 1))) {
      out.push(`### ${e.id}`, '');
      out.push(`- normative_status: ${e.normative_status || 'MISSING'}`);
      out.push(`- owners: ${(e.owners || []).join(', ') || 'MISSING'}`);
      out.push(`- source_anchor: ${e.source_anchor || 'MISSING'}`);
      out.push(`- statement: ${e.statement || 'MISSING'}`, '');
    }
  }
  return `${out.join('\n').replace(/\n+$/, '')}\n`;
}

/** Is the generated index still what the catalog says? */
export function checkContractIndex(root) {
  const entries = parseContractCatalog(root);
  if (!entries) return [{ code: 'CATALOG_SOURCE_MISSING', detail: `${CATALOG_SOURCE_PATH} is absent, so ${CATALOG_INDEX_PATH} cannot be derived` }];
  if (!entries.length) return [{ code: 'CATALOG_SOURCE_EMPTY', detail: `${CATALOG_SOURCE_PATH} declares no ids` }];
  if (!existsSync(join(root, CATALOG_INDEX_PATH))) {
    // Not generated yet. That is a recorded gap, not drift, and it stays non-blocking
    // only while the file is absent: once it exists, any mismatch below is a refusal.
    return [{ code: 'CATALOG_NOT_GENERATED', detail: `${CATALOG_INDEX_PATH} has not been generated; the generator is ready and waits on adding that path to the write allow-list` }];
  }
  if (readFileSync(join(root, CATALOG_INDEX_PATH), 'utf8') !== renderContractIndex(root)) {
    return [{ code: 'STALE_GENERATED_CATALOG', detail: `${CATALOG_INDEX_PATH} no longer matches ${CATALOG_SOURCE_PATH}; regenerate with \`docs:sync --write\`, never hand-edit` }];
  }
  return [];
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  // `--root` was accepted and ignored: every caller that passed one -- my own controls
  // among them, which is how this surfaced -- got a verdict about whichever tree this
  // script happens to live in, while believing it had been pointed elsewhere. A flag
  // that is silently not honoured is worse than one that is refused outright.
  let root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const args = process.argv.slice(2);
  const rootAt = args.indexOf('--root');
  if (rootAt !== -1 && args[rootAt + 1]) root = resolve(args[rootAt + 1]);
  const write = args.includes('--write');
  const check = args.includes('--check');
  if (!write && !check) {
    console.error('usage: gen-current-state.mjs --check | --write [--root <dir>]');
    process.exit(2);
  }
  const result = build(root);
  if (result.refused) {
    console.log(`REFUSED ${result.refused}`);
    process.exit(2);
  }
  // Printed once, and printed with the shared classification. The loop that used to sit
  // here labelled every finding FAIL regardless of severity, so a recorded non-blocking
  // gap was announced as a refusal and then announced again below as a warning.
  const blockingNow = result.findings.filter(isBlockingFinding);
  const writeBlocking = result.findings.filter((f) => isBlockingFinding(f) && !SELF_UPDATE_CODES.includes(f.code));
  for (const f of result.findings) console.log(`${isBlockingFinding(f) ? 'FAIL' : 'WARN'} ${f.code}: ${f.detail}`);
  console.log(`runtime: branch=${result.runtime.branch} head=${String(result.runtime.head).slice(0, 9)} merged_into_master=${result.runtime.merged_into_master} dirty_paths=${result.runtime.dirty_paths} (live state, not persisted in the view)`);
  const target = join(root, 'dev/engineering/current-state.json');
  const rendered = renderView(result);
  if (write) {
    if (writeBlocking.length) {
      console.log(`REFUSED write: ${writeBlocking.length} blocking finding(s) above (a fake verification claim is never written into the derived view)`);
      process.exit(1);
    }
    const written = writeGenerated(root, 'dev/engineering/current-state.json', rendered);
    if (!written.ok) {
      console.log(`REFUSED WRITE_BOUNDARY: ${written.why}`);
      process.exit(2);
    }
    console.log(`wrote dev/engineering/current-state.json entries=${result.view.entries.length}`);
    process.exit(0);
  }
  if (!existsSync(target)) {
    console.log('FAIL STALE_GENERATED_VIEW: dev/engineering/current-state.json missing (run --write)');
    process.exit(1);
  }
  const current = readFileSync(target, 'utf8');
  if (current !== rendered) {
    console.log('FAIL STALE_GENERATED_VIEW: derived view does not match registry+git; run pnpm docs:sync --write');
    process.exit(1);
  }
  // Same classification as docs:sync --check and docs:probe. This entry point exited on
  // any finding at all, so it called a recorded non-blocking gap a refusal while the
  // probe reported the very same input as non_blocking — and it printed the gap as FAIL.
  console.log(`gen-current-state: view fresh entries=${result.view.entries.length} findings=${result.findings.length} blocking=${blockingNow.length}`);
  process.exit(blockingNow.length ? 1 : 0);
}

#!/usr/bin/env node
// EB1-A / EB1-B document validators (Engineering Baseline, first version).
//
// Pure Node, no third-party dependency: this must run in an isolated worktree
// that has no node_modules installed. The YAML it reads is the strict subset
// described in .agents/notes/README.md; unsupported syntax FAILS loudly rather
// than being silently mis-parsed.
//
// Exit codes: 0 = pass, 1 = findings, 2 = refused (unusable input).

import { readFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import { join, dirname, resolve, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

export const LIFECYCLE = ['proposed', 'implemented', 'rejected', 'archived'];
const ID_RE = /^EB-ADR-\d{4}$/;
const REQID_RE = /^(REQ|INV|AC|IDEA)-[A-Z0-9-]+$/;
const CONCEPT_RE = /^C-EB-\d{4}$/;
const REQUIRED_SECTIONS = ['## Context', '## Decision', '## Consequences'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/** Parse the strict frontmatter subset. Returns {data, body, errors}. */
export function parseFrontmatter(text) {
  const errors = [];
  const lines = text.split(/\r?\n/);
  if (lines[0] !== '---') return { data: null, errors: ['frontmatter-missing'] };
  const end = lines.indexOf('---', 1);
  if (end === -1) return { data: null, errors: ['frontmatter-unclosed'] };
  const data = {};
  let currentListKey = null;
  for (let i = 1; i < end; i++) {
    const raw = lines[i];
    if (!raw.trim() || raw.trimStart().startsWith('#')) continue;
    const listItem = raw.match(/^\s+-\s+(.*)$/);
    if (listItem && currentListKey) {
      data[currentListKey].push(strip(listItem[1]));
      continue;
    }
    const kv = raw.match(/^([A-Za-z_][A-Za-z0-9_]*):\s*(.*)$/);
    if (!kv) {
      errors.push(`frontmatter-unsupported-syntax:L${i + 1}:${raw.trim()}`);
      currentListKey = null;
      continue;
    }
    const [, key, rawValue] = kv;
    const value = rawValue.trim();
    if (value === '') {
      data[key] = [];
      currentListKey = key;
      continue;
    }
    currentListKey = null;
    if (value.startsWith('[') && value.endsWith(']')) {
      const inner = value.slice(1, -1).trim();
      data[key] = inner ? inner.split(',').map((s) => strip(s.trim())) : [];
    } else {
      data[key] = strip(value);
    }
  }
  const body = lines.slice(end + 1).join('\n');
  return { data, body, errors };
}

function strip(s) {
  return s.replace(/^['"]|['"]$/g, '').trim();
}

/** Read the stable-id index (docs/contracts/engineering-baseline/ids.yaml). */
export function loadContractIds(root) {
  const file = join(root, 'docs/contracts/engineering-baseline/ids.yaml');
  if (!existsSync(file)) return { ids: new Set(), errors: ['contract-id-index-missing'] };
  const ids = new Set();
  for (const raw of readFileSync(file, 'utf8').split(/\r?\n/)) {
    const m = raw.match(/^\s*-?\s*id:\s*(\S+)/);
    if (m) ids.add(m[1]);
  }
  return { ids, errors: [], file: relative(root, file) };
}

/** Read concept ids declared in docs/glossary.md table rows. */
export function loadGlossaryConcepts(root) {
  const file = join(root, 'docs/glossary.md');
  if (!existsSync(file)) return new Set();
  const concepts = new Set();
  for (const raw of readFileSync(file, 'utf8').split(/\r?\n/)) {
    const m = raw.match(/^\|\s*(C-EB-\d{4})\s*\|/);
    if (m) concepts.add(m[1]);
  }
  return concepts;
}

function isPathReference(ref) {
  return ref.includes('/') || ref.endsWith('.md') || ref.endsWith('.yaml');
}

/** Validate one note file. Returns findings array of {code, detail}. */
export function validateNote(root, absPath, ctx) {
  const findings = [];
  const rel = relative(root, absPath).split(sep).join('/');
  const text = readFileSync(absPath, 'utf8');
  const { data, body, errors } = parseFrontmatter(text);
  for (const e of errors) findings.push({ code: 'note-frontmatter', detail: `${rel}: ${e}` });
  if (!data) return findings;

  const parentDir = rel.split('/').slice(-2, -1)[0];
  if (!LIFECYCLE.includes(parentDir)) {
    findings.push({ code: 'note-location', detail: `${rel}: not under a lifecycle directory` });
  } else if (data.status !== parentDir) {
    findings.push({
      code: 'note-status-dir-mismatch',
      detail: `${rel}: status=${String(data.status)} but directory=${parentDir}`,
    });
  }
  if (!ID_RE.test(String(data.id || ''))) {
    findings.push({ code: 'note-id-grammar', detail: `${rel}: id=${String(data.id)}` });
  } else if (ctx.seenIds.has(data.id)) {
    findings.push({
      code: 'note-id-duplicate',
      detail: `${rel}: id ${data.id} already declared in ${ctx.seenIds.get(data.id)}`,
    });
  } else {
    ctx.seenIds.set(data.id, rel);
  }
  if (!data.title) findings.push({ code: 'note-title-missing', detail: rel });
  if (data.status !== 'proposed' && !DATE_RE.test(String(data.decided || ''))) {
    findings.push({ code: 'note-decided-required', detail: `${rel}: status=${data.status} needs decided: YYYY-MM-DD` });
  }
  if (data.status === 'archived' && !data.supersedes) {
    findings.push({ code: 'note-archived-needs-successor', detail: rel });
  }
  for (const section of REQUIRED_SECTIONS) {
    if (!body.includes(section)) {
      findings.push({ code: 'note-section-missing', detail: `${rel}: ${section}` });
    }
  }

  for (const ref of Array.isArray(data.references) ? data.references : []) {
    if (CONCEPT_RE.test(ref)) {
      if (!ctx.concepts.has(ref)) {
        findings.push({ code: 'note-reference-unknown-concept', detail: `${rel}: ${ref} not declared in docs/glossary.md` });
      }
    } else if (REQID_RE.test(ref)) {
      if (!ctx.contractIds.has(ref)) {
        findings.push({ code: 'note-reference-unknown-id', detail: `${rel}: ${ref}` });
      }
    } else if (isPathReference(ref)) {
      if (!existsSync(join(root, ref))) {
        findings.push({ code: 'note-reference-missing-path', detail: `${rel}: ${ref}` });
      }
    } else {
      findings.push({ code: 'note-reference-unclassified', detail: `${rel}: ${ref}` });
    }
  }

  const verified = Array.isArray(data.verified_by) ? data.verified_by : [];
  if (data.status === 'implemented' && verified.length === 0) {
    findings.push({ code: 'note-implemented-needs-evidence', detail: rel });
  }
  if (data.status !== 'implemented' && verified.length > 0) {
    findings.push({ code: 'note-false-delivery-claim', detail: `${rel}: status=${data.status} must not carry verified_by` });
  }
  for (const v of verified) {
    if (!existsSync(join(root, v))) {
      findings.push({ code: 'note-verified-by-missing', detail: `${rel}: ${v} (NOT_VERIFIED)` });
    }
  }
  return findings;
}

export function walkNotes(root) {
  const out = [];
  const base = join(root, '.agents/notes');
  if (!existsSync(base)) return out;
  for (const dir of readdirSync(base)) {
    const full = join(base, dir);
    if (!statSync(full).isDirectory() || !LIFECYCLE.includes(dir)) continue;
    for (const name of readdirSync(full)) {
      if (name.endsWith('.md') && name !== 'README.md') out.push(join(full, name));
    }
  }
  return out.sort();
}

export function run(root) {
  const contract = loadContractIds(root);
  const ctx = { seenIds: new Map(), contractIds: contract.ids, concepts: loadGlossaryConcepts(root) };
  const findings = contract.errors.map((e) => ({ code: 'contract-index', detail: e }));
  const notes = walkNotes(root);
  for (const n of notes) findings.push(...validateNote(root, n, ctx));
  return { checked: notes.length, findings };
}

const invokedDirectly = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  const argRoot = (() => {
    const i = process.argv.indexOf('--root');
    return i > -1 && process.argv[i + 1]
      ? resolve(process.argv[i + 1])
      : resolve(dirname(fileURLToPath(import.meta.url)), '..');
  })();
  if (!existsSync(join(argRoot, '.agents'))) {
    console.error(`REFUSED: ${argRoot} has no .agents directory`);
    process.exit(2);
  }
  const { checked, findings } = run(argRoot);
  for (const f of findings) console.log(`FAIL ${f.code}: ${f.detail}`);
  console.log(`verify-agent-notes: root=${argRoot} notes=${checked} findings=${findings.length}`);
  process.exit(findings.length ? 1 : 0);
}
